def collatz_sequence(n):
    """
    Computes the Collatz sequence for n, returning a list of integers.
    The sequence ends when it reaches 1.
    """
    sequence = [n]
    while n != 1:
        if n % 2 == 0:
            n = n // 2
        else:
            n = 3 * n + 1
        sequence.append(n)
    return sequence

def get_odd_collatz_numbers(n):
    """
    Computes the Collatz sequence for n and returns a sorted list of odd numbers found in the sequence.
    """
    sequence = collatz_sequence(n)
    odd_numbers = [num for num in sequence if num % 2 != 0]
    return sorted(odd_numbers)

def main():
    try:
        n = int(input("Enter a positive integer: "))
        if n <= 0:
            print("Please enter a positive integer.")
            return

        odd_numbers = get_odd_collatz_numbers(n)
        print(f"Sorted odd numbers in the Collatz sequence for {n}: {odd_numbers}")
    except ValueError:
        print("Invalid input. Please enter a valid integer.")

if __name__ == "__main__":
    main()
